    $('gsVerifyInventory').onclick=event=>action(event.currentTarget,async()=>{const checked=await request('/'+r.id+'/verify-algorithm-inventory',{});await refresh();selected=checked.id;draw();message('Package verified. Adapter installation and qualification are pending.');});
